classDiagram %% Core Domain Classes class Customer { -String accountNumber -String name -String address -String telephoneNumber -String email -Date registrationDate -CustomerStatus status +Customer(accountNumber, name, address, phone) +validateAccountNumber() boolean +updateContactInfo(address, phone) void +getCustomerSummary() String +isActive() boolean }
class Item { -String itemCode -String itemName -String category -double unitPrice -int stockQuantity -String description -Date lastUpdated +Item(code, name, category, price) +updatePrice(newPrice) void +updateStock(quantity) void +isAvailable() boolean +calculateSubTotal(quantity) double }
class Bill { -String billNumber -String customerAccountNumber -Date billDate -double totalAmount -double taxAmount -BillStatus status -List~BillItem~ billItems +Bill(customerAccountNumber) +addBillItem(item, quantity) void +calculateTotal() double +applyDiscount(percentage) void +generateBillNumber() String +printBill() void }
class BillItem { -String itemCode -String itemName -int quantity -double unitPrice -double subTotal +BillItem(itemCode, quantity, unitPrice) +calculateSubTotal() double +updateQuantity(newQuantity) void }
%% System Classes class User { -String username -String password -String fullName -UserRole role -Date lastLogin -boolean isActive +User(username, password, role) +authenticate(password) boolean +changePassword(oldPass, newPass) boolean +hasPermission(action) boolean }
class Session { -String sessionId -String username -Date loginTime -Date lastActivity -boolean isActive +Session(username) +validateSession() boolean +refreshSession() void +terminateSession() void }
%% Service Classes class CustomerService { -CustomerRepository repository +registerCustomer(customerData) Customer +updateCustomer(accountNumber, data) boolean +findCustomer(accountNumber) Customer +searchCustomers(criteria) List~Customer~ +validateCustomerData(data) ValidationResult }
class ItemService { -ItemRepository repository +addItem(itemData) Item +updateItem(itemCode, data) boolean +deleteItem(itemCode) boolean +findItem(itemCode) Item +getItemsByCategory(category) List~Item~ +updateInventory(itemCode, quantity) boolean }
class BillingService { -BillRepository repository -CustomerService customerService -ItemService itemService +createBill(customerAccountNumber) Bill +addItemToBill(billNumber, itemCode, quantity) void +calculateBillTotal(billNumber) double +processBill(billNumber) boolean +getBillHistory(customerAccountNumber) List~Bill~ }
class AuthenticationService { -UserRepository userRepository +authenticateUser(username, password) Session +createSession(username) Session +validateSession(sessionId) boolean +logout(sessionId) boolean }
%% Repository Classes (Data Access Layer) class CustomerRepository { -String dataFilePath +save(customer) boolean +findById(accountNumber) Customer +findAll() List~Customer~ +update(customer) boolean +delete(accountNumber) boolean +searchByName(name) List~Customer~ }
class ItemRepository { -String dataFilePath +save(item) boolean +findById(itemCode) Item +findAll() List~Item~ +update(item) boolean +delete(itemCode) boolean +findByCategory(category) List~Item~ }
class BillRepository { -String dataFilePath +save(bill) boolean +findById(billNumber) Bill +findByCustomer(accountNumber) List~Bill~ +findAll() List~Bill~ +update(bill) boolean }
class UserRepository { -String dataFilePath +save(user) boolean +findByUsername(username) User +findAll() List~User~ +update(user) boolean }
%% Controller Classes class SystemController { -AuthenticationService authService -Session currentSession +login(username, password) boolean +logout() boolean +showMainMenu() void +handleUserInput() void }
class CustomerController { -CustomerService customerService +registerNewCustomer() void +editCustomerInfo() void +displayCustomerDetails() void +searchCustomer() void }
class ItemController { -ItemService itemService +addNewItem() void +updateItemInfo() void +deleteItem() void +displayItems() void +manageInventory() void }
class BillingController { -BillingService billingService +createNewBill() void +addItemsToBill() void +calculateAndPrintBill() void +viewBillHistory() void }
%% Utility Classes class FileManager { +readFromFile(filePath) List~String~ +writeToFile(filePath, data) boolean +appendToFile(filePath, data) boolean +backupFile(filePath) boolean }
class ValidationUtils { +validateAccountNumber(accountNumber) boolean +validatePhoneNumber(phone) boolean +validateEmail(email) boolean +validateItemCode(itemCode) boolean }
class ReportGenerator { +generateCustomerReport() String +generateSalesReport(dateRange) String +generateInventoryReport() String }
%% Enumerations class CustomerStatus { <<enumeration>> ACTIVE INACTIVE SUSPENDED }
class UserRole { <<enumeration>> STAFF ADMIN MANAGER }
class BillStatus { <<enumeration>> DRAFT PROCESSED PAID CANCELLED }
%% Relationships
Bill o--o{ BillItem : "contains" Item ||--o{ BillItem : "included in"
CustomerService -- CustomerRepository : "uses" ItemService -- ItemRepository : "uses" BillingService -- BillRepository : "uses" AuthenticationService -- UserRepository : "uses"
BillingService o-- CustomerService : "depends on" BillingService o-- ItemService : "depends on"
SystemController o-- AuthenticationService : "uses" CustomerController o-- CustomerService : "uses" ItemController o-- ItemService : "uses" BillingController o-- BillingService : "uses"
User ||--o{ Session : "creates" Customer ||--|| CustomerStatus : "has" User ||--|| UserRole : "has" Bill ||--|| BillStatus : "has"
CustomerRepository ..> FileManager : "uses" ItemRepository ..> FileManager : "uses" BillRepository ..> FileManager : "uses" UserRepository ..> FileManager : "uses"
CustomerService ..> ValidationUtils : "uses" ItemService ..> ValidationUtils : "uses"

